import{_ as t,o,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Keynotes: Supermicro® SuperStorage Systems Based on New Intel® Xeon® Scalable Pro... - David Ramirez","description":"","frontmatter":{"title":"Keynotes: Supermicro® SuperStorage Systems Based on New Intel® Xeon® Scalable Pro... - David Ramirez","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["分布式存储","Ceph","高性能存储","服务器解决方案","NVMe"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynotes_-_Supermicro_SuperStorage_Systems_Based_on_New_Intel_Xeon_Scalable_Pro..._-_David_Ramirez.md","filePath":"posts/2019/Keynotes_-_Supermicro_SuperStorage_Systems_Based_on_New_Intel_Xeon_Scalable_Pro..._-_David_Ramirez.md","lastUpdated":1780459816000}'),s={name:"posts/2019/Keynotes_-_Supermicro_SuperStorage_Systems_Based_on_New_Intel_Xeon_Scalable_Pro..._-_David_Ramirez.md"};function i(_,e,n,a,p,m){return o(),r("div",null,[...e[0]||(e[0]=[l("<p>会议纪要：</p><p><strong>会议时间</strong>： 未知 <strong>会议主题</strong>： 新一代数据中心存储技术及服务器解决方案讨论 <strong>参会人员</strong>： 未知 <strong>会议内容</strong>：</p><p><strong>一、会议关键细节</strong></p><ol><li><p><strong>新技术介绍</strong>：</p><ul><li>基于NVMe的数据中心持久内存（DC persistent memory）。</li><li>新一代Intel Xeon Scalable Pro CPU，性能提升55%，价格与上一代相同。</li><li>新存储技术，性能提升，价格更具优势。</li></ul></li><li><p><strong>服务器解决方案</strong>：</p><ul><li>标准密度存储服务器，支持3.5英寸和2.5英寸硬盘，混合解决方案可包括NVMe。</li><li>特殊服务器，可容纳多达60个硬盘驱动器，支持多种存储类型，包括NVMe和DC persistent memory。</li><li>网络支持，推荐25Gbps和100Gbps网络，支持高性能和低延迟。</li></ul></li><li><p><strong>硬件支持</strong>：</p><ul><li>支持205个核心的Intel Xeon Scalable CPU。</li><li>支持24个DDR4内存插槽，最高支持6TB RAM。</li><li>支持8TB NVMe SSD和48TB DC persistent memory。</li></ul></li></ol><p><strong>二、讨论的主要议题</strong></p><ol><li>新一代存储技术及其性能优势。</li><li>服务器解决方案的适用场景和优势。</li><li>网络和硬件支持对存储性能的影响。</li></ol><p><strong>三、决定的事项</strong></p><ol><li>推广新一代存储技术和服务器解决方案。</li><li>优化网络和硬件配置，提升存储性能。</li><li>研究DC persistent memory的应用场景。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>关注新技术发展，及时更新产品。</li><li>与合作伙伴共同推广存储解决方案。</li><li>深入研究DC persistent memory的应用，探索新的应用场景。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议介绍了新一代存储技术和服务器解决方案，讨论了相关议题，并制定了后续行动计划。通过技术创新和产品优化，旨在为客户提供更优质、更高效的存储解决方案。会议强调了NVMe和DC persistent memory等新技术的应用，同时讨论了服务器和网络配置对性能的影响。</p>",12)])])}const d=t(s,[["render",i]]);export{g as __pageData,d as default};
